import sys
input = sys.stdin.read

def solve():
    n = int(input().strip())
    full_weeks = n // 7
    extra_days = n % 7

    min_days_off = full_weeks * 2
    max_days_off = full_weeks * 2

    if 999000 <= n <= 1000000:
        if extra_days > 0:
            max_days_off += max(2, extra_days)
    else:
        if extra_days > 0:
            max_days_off += min(2, extra_days)

    print(min_days_off, max_days_off)

solve()
